+/* ============================================================================
+   2. PET OVERLAY (transparent window: pet sprite + bubble)
+============================================================================ */
+html, body.overlay {
+  background: transparent !important;
+  overflow: hidden;
+  width: 100%;
+  height: 100%;
+  font-family: var(--font-ui);
+  cursor: default;
+}
+body.overlay, body.overlay * {
+  user-select: none;
+  -webkit-user-select: none;
+}
+
+#pet-root {
+  position: absolute;
+  bottom: 0;
+  left: 50%;
+  transform: translateX(-50%);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 5px;
+}
+#pet {
+  image-rendering: pixelated;
+  cursor: grab;
+}
+
+/* speech bubble: ember glass */
+.bubble {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  gap: 3px;
+  max-width: 270px;
+  padding: 9px 15px;
+  border-radius: 16px;
+  background: var(--bubble-bg, rgba(24, 18, 12, 0.92));
+  color: var(--bubble-fg, #F6F0E4);
+  border: 1px solid var(--bubble-border, rgba(232, 176, 106, 0.22));
+  font-size: var(--bubble-font-size, 12px);
+  font-family: var(--bubble-font-family, var(--font-ui));
+  font-weight: 500;
+  line-height: 1.45;
+  text-align: center;
+  margin-bottom: 6px;
+  box-shadow:
+    0 10px 30px rgba(0, 0, 0, 0.45),
+    0 2px 8px rgba(0, 0, 0, 0.28),
+    inset 0 1px 0 rgba(255, 255, 255, 0.06);
+  transition: opacity 0.2s ease, transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
+}
+.bubble[hidden] { display: none; }
+.bubble::after {
+  content: "";
+  position: absolute;
+  left: 50%;
+  bottom: -6px;
+  transform: translateX(-50%);
+  border: 7px solid transparent;
+  border-top: 7px solid var(--bubble-bg, rgba(24, 18, 12, 0.92));
+  border-bottom: 0;
+}
+.bubble .brow.focusable { cursor: pointer; border-radius: 8px; transition: background 0.12s; }
+.bubble .brow.focusable:hover { background: rgba(255, 255, 255, 0.10); }
+.bubble .approval { display: inline-flex; gap: 5px; margin-left: 6px; }
+.bubble .approval button {
+  font: inherit; font-size: 10px; font-weight: 600;
+  border: none; border-radius: 999px; padding: 1px 9px; cursor: pointer;
+}
+.bubble .approval .ap-allow { background: rgba(143, 216, 168, 0.16); color: var(--green); }
+.bubble .approval .ap-deny { background: rgba(229, 122, 110, 0.18); color: var(--red); }
+.bubble .brow {
+  display: flex;
+  align-items: center;
+  gap: 5px;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+  max-width: 330px;
+}
+.bubble .single-line {
+  transition: opacity 0.18s ease;
+  white-space: nowrap;
+  overflow: hidden;
+  text-overflow: ellipsis;
+  max-width: 330px;
+}
+.bubble .single-line.fade { opacity: 0; }
+.bubble.capsule { border-radius: 999px; }
+
+.bubble .aicon { width: 14px; height: 14px; flex: 0 0 auto; object-fit: contain; }
+.bubble .rtitle { font-weight: 600; opacity: 0.88; overflow: hidden; text-overflow: ellipsis; max-width: 110px; }
+.bubble .rproject { font-weight: 500; opacity: 0.82; overflow: hidden; text-overflow: ellipsis; max-width: 110px; }
+.bubble .rsep { opacity: 0.35; }
+.bubble .amsg { font-weight: 500; opacity: 0.85; overflow: hidden; text-overflow: ellipsis; flex-shrink: 1; }
+.bubble .rstate { font-size: 0.85em; opacity: 0.55; }
+.bubble .clock { font-size: 0.85em; opacity: 0.45; font-variant-numeric: tabular-nums; }
+.bubble .xn {
+  font-size: 0.85em; font-weight: 600; opacity: 0.65;
+  padding: 0 6px; border-radius: 999px; background: rgba(255,255,255,0.10);
+}
+
+.bubble .brow.waiting .amsg {
+  color: var(--orange); font-weight: 600;
+  animation: waitflash 1.7s ease-in-out infinite;
+}
+@keyframes waitflash { 0%, 100% { opacity: 1; } 50% { opacity: 0.65; } }
+
+.bubble .amsg.shimmer {
+  background: linear-gradient(100deg,
+    var(--bubble-fg, #F6F0E4) 40%, rgba(255,255,255,0.45) 50%, var(--bubble-fg, #F6F0E4) 60%);
+  background-size: 220% 100%;
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+  animation: shimmer 2.5s linear infinite;
+}
+@keyframes shimmer { from { background-position: 120% 0; } to { background-position: -120% 0; } }
+
+.bubble .sdot {
+  position: relative; width: 8px; height: 8px; border-radius: 50%;
+  flex: 0 0 auto; background: #8A8578;
+}
+.bubble .brow[data-state="working"] .sdot,
+.bubble .brow[data-state="registered"] .sdot { background: var(--amber); }
+.bubble .brow[data-state="waiting"] .sdot { background: var(--orange); }
+.bubble .brow[data-state="done"] .sdot { background: var(--green); }
+.bubble .sdot.plain.spin::after {
+  content: ""; position: absolute; inset: 0; border-radius: 50%;
+  background: inherit;
+  animation: bloom 1.5s ease-out infinite;
+}
+@keyframes bloom { 0% { transform: scale(1); opacity: 0.55; } 100% { transform: scale(2.4); opacity: 0; } }
+
+.bubble .sdot.claude { width: 14px; height: 14px; border-radius: 0; background: transparent !important; }
+.bubble .sdot.claude::after {
+  content: "✻"; font-size: 12px; font-weight: 700; line-height: 14px;
