+
+.bubble .brow.waiting .amsg {
+  color: var(--orange); font-weight: 600;
+  animation: waitflash 1.7s ease-in-out infinite;
+}
+@keyframes waitflash { 0%, 100% { opacity: 1; } 50% { opacity: 0.65; } }
+
+.bubble .amsg.shimmer {
+  background: linear-gradient(100deg,
+    var(--bubble-fg, #F6F0E4) 40%, rgba(255,255,255,0.45) 50%, var(--bubble-fg, #F6F0E4) 60%);
+  background-size: 220% 100%;
+  -webkit-background-clip: text;
+  background-clip: text;
+  color: transparent;
+  animation: shimmer 2.5s linear infinite;
+}
+@keyframes shimmer { from { background-position: 120% 0; } to { background-position: -120% 0; } }
+
+.bubble .sdot {
+  position: relative; width: 8px; height: 8px; border-radius: 50%;
+  flex: 0 0 auto; background: #8A8578;
+}
+.bubble .brow[data-state="working"] .sdot,
+.bubble .brow[data-state="registered"] .sdot { background: var(--amber); }
+.bubble .brow[data-state="waiting"] .sdot { background: var(--orange); }
+.bubble .brow[data-state="done"] .sdot { background: var(--green); }
+.bubble .sdot.plain.spin::after {
+  content: ""; position: absolute; inset: 0; border-radius: 50%;
+  background: inherit;
+  animation: bloom 1.5s ease-out infinite;
+}
+@keyframes bloom { 0% { transform: scale(1); opacity: 0.55; } 100% { transform: scale(2.4); opacity: 0; } }
+
+.bubble .sdot.claude { width: 14px; height: 14px; border-radius: 0; background: transparent !important; }
+.bubble .sdot.claude::after {
+  content: "✻"; font-size: 12px; font-weight: 700; line-height: 14px;
+  display: block; text-align: center;
+}
+.bubble .brow[data-state="working"] .sdot.claude::after,
+.bubble .brow[data-state="registered"] .sdot.claude::after { color: var(--amber); }
