+  font-family: var(--font-ui);
+}
+
+.floating-ball-body #ball {
+  position: absolute;
+  top: var(--ball-margin);
+  left: var(--ball-margin);
+  width: var(--ball-size);
+  height: var(--ball-size);
+  aspect-ratio: 1 / 1;
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  cursor: grab;
+  user-select: none;
+  -webkit-user-select: none;
+
+  /* ember glass orb */
+  background:
+    radial-gradient(circle at 36% 26%, rgba(255, 236, 205, 0.55) 0%, rgba(255, 222, 178, 0.18) 34%, transparent 46%),
+    radial-gradient(circle at 62% 78%, rgba(0, 0, 0, 0.42) 0%, transparent 52%),
+    linear-gradient(160deg, #8A6236 0%, #4A3218 45%, #241708 100%);
+  border: 1.5px solid rgba(255, 222, 178, 0.40);
+  box-shadow:
+    0 3px 8px rgba(0, 0, 0, 0.5),
+    0 0 10px rgba(232, 176, 106, 0.25),
+    inset 0 2px 3px rgba(255, 236, 205, 0.35),
+    inset 0 -3px 6px rgba(0, 0, 0, 0.45),
+    0 0 0 1px rgba(0, 0, 0, 0.15);
+  transition: transform 0.18s cubic-bezier(0.22, 1, 0.36, 1),
+              box-shadow 0.18s ease;
+}
+.floating-ball-body #ball:hover {
+  transform: scale(1.05);
+  box-shadow:
+    0 3px 10px rgba(0, 0, 0, 0.5),
+    0 0 12px rgba(232, 176, 106, 0.38),
+    inset 0 2px 3px rgba(255, 236, 205, 0.42),
+    inset 0 -3px 6px rgba(0, 0, 0, 0.45),
+    0 0 0 1px rgba(0, 0, 0, 0.15);
+}
+.floating-ball-body #ball.pressed { transform: scale(0.96); }
+.floating-ball-body #ball.dragging,
+.floating-ball-body #ball.dragging:hover {
+  transform: none;
+  filter: none;
+  transition: none;
+  box-shadow: none;
+  cursor: grabbing;
+}
+.floating-ball-body #ball canvas {
+  width: 62%;
+  height: 62%;
+  aspect-ratio: 1 / 1;
+  border-radius: 50%;
+  image-rendering: pixelated;
+  pointer-events: none;
+  -webkit-user-drag: none;
+}
