import { beforeEach, describe, expect, it, vi } from "vitest";

const nativeWindow = vi.hoisted(() => ({
  scaleFactor: vi.fn(),
  outerPosition: vi.fn(),
  setPosition: vi.fn(),
  onMoved: vi.fn(),
