  1	// Shared window-position helpers. Both the engine (tick loop) and the physics
  2	// module (throw/fall) need to read and write the pet window's logical position;
  3	// centralizing it keeps the DPI conversion in one place and avoids two copies
  4	// of the same `outerPosition / scaleFactor` dance drifting apart.
  5	
  6	import { getCurrentWindow } from "@tauri-apps/api/window";
  7	import { LogicalPosition } from "@tauri-apps/api/dpi";
  8	import type { Point } from "./types";
  9	
 10	const win = getCurrentWindow();
 11	
 12	let cachedLogicalPos: Point | null = null;
 13	let cacheGeneration = 0;
 14	let pendingPositionRead: Promise<Point | null> | null = null;
 15	let pendingMovedPosition: Promise<void> | null = null;
 16	let trackingStarted = false;
 17	let pendingTracking: Promise<void> | null = null;
 18	
 19	function copyPoint(pos: Point): Point {
 20	  return { x: pos.x, y: pos.y };
 21	}
 22	
 23	function invalidatePosition(): number {
 24	  cacheGeneration += 1;
 25	  cachedLogicalPos = null;
 26	  return cacheGeneration;
 27	}
 28	
 29	function refreshMovedPosition(physical: Point): void {
 30	  const generationAtMove = invalidatePosition();
 31	  let update: Promise<void>;
 32	  update = win.scaleFactor()
 33	    .then((scaleFactor) => {
 34	      if (generationAtMove !== cacheGeneration) return;
 35	      cachedLogicalPos = {
 36	        x: physical.x / scaleFactor,
 37	        y: physical.y / scaleFactor,
 38	      };
 39	    })
 40	    .catch(() => {
 41	      // Keep the cache invalid; the regular reader retries when it is needed.
 42	    })
 43	    .finally(() => {
 44	      if (pendingMovedPosition === update) pendingMovedPosition = null;
 45	    });
 46	  pendingMovedPosition = update;
 47	}
 48	
 49	function startPositionTracking(): void {
 50	  if (trackingStarted || pendingTracking) return;
 51	  const movedRegistration = Promise.resolve().then(() =>
 52	    win.onMoved(({ payload }) => {
 53	      refreshMovedPosition(payload);
 54	    }),
 55	  );
 56	  const scaleRegistration = Promise.resolve().then(() =>
 57	    win.onScaleChanged(() => {
 58	      if (!pendingMovedPosition) invalidatePosition();
 59	    }),
 60	  );
 61	  pendingTracking = Promise.allSettled([movedRegistration, scaleRegistration])
 62	    .then(([moved, scale]) => {
 63	      if (moved.status === "fulfilled" && scale.status === "fulfilled") {
 64	        trackingStarted = true;
 65	        return;
 66	      }
 67	      if (moved.status === "fulfilled") moved.value();
 68	      if (scale.status === "fulfilled") scale.value();
 69	    })
 70	    .finally(() => {
 71	      pendingTracking = null;
 72	    });
 73	}
 74	
 75	/// Current window position in LOGICAL pixels (DPI-divided). Returns null if the
 76	/// window or scaleFactor can't be read (e.g. window closing).
 77	export async function currentLogicalPos(): Promise<Point | null> {
 78	  startPositionTracking();
 79	  if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 80	  while (pendingMovedPosition) {
 81	    const update = pendingMovedPosition;
 82	    await update;
 83	    if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 84	    if (pendingMovedPosition === update) break;
 85	  }
 86	  if (!pendingPositionRead) {
 87	    const generationAtReadStart = cacheGeneration;
 88	    pendingPositionRead = (async () => {
 89	      try {
 90	        const sf = await win.scaleFactor();
 91	        const p = await win.outerPosition();
 92	        if (generationAtReadStart !== cacheGeneration) {
 93	          return cachedLogicalPos ? copyPoint(cachedLogicalPos) : null;
 94	        }
 95	        cachedLogicalPos = { x: p.x / sf, y: p.y / sf };
 96	        return copyPoint(cachedLogicalPos);
 97	      } catch {
 98	        return null;
 99	      } finally {
100	        pendingPositionRead = null;
101	      }
102	    })();
103	  }
104	  const pos = await pendingPositionRead;
105	  return pos ? copyPoint(pos) : null;
106	}
107	
108	/// Move the window to a logical-pixel position. Caller is responsible for
109	/// clamping to the work area first.
110	export async function setLogical(pos: Point): Promise<void> {
111	  const generationAtSetStart = invalidatePosition();
112	  await win.setPosition(new LogicalPosition(pos.x, pos.y));
113	  if (generationAtSetStart === cacheGeneration) {
114	    cachedLogicalPos = copyPoint(pos);
115	  }
116	}
 70	  petRef?.setRow(row);
 71	}
 72	
 73	/// One engine tick. Priority: throw > drag-sample > drag-release > mood-pause > sleep > mode.
 74	/// Returns true when the pet is actively moving/interacting and needs the fast
 75	/// (30ms) tick; false when resting/sleeping/stationary so the loop can use the
 76	/// idle (200ms) tick and skip most IPC calls.
 77	async function tick(): Promise<boolean> {
 78	  if (isThrowing()) return true;
 79	  if (dragging) {
 80	    const pos = await currentLogicalPos();
 81	    if (pos) recordSample(pos);
 82	    return true;
 83	  }
 84	  if (releasePending) {
 85	    releasePending = false;
 86	    const vel = releaseVelocity();
 87	    clearSamples();
 88	    if (vel && Math.hypot(vel.vx, vel.vy) > THROW_MIN_SPEED) {
 89	      wake();
 90	      await handleDragRelease(vel);
 91	      return true;
 92	    }
 93	  }
 94	
 95	  // Mood-driven freeze: keep the pet still while the user needs to see the
 96	  // bubble or the celebrate burst. Throws and drags above still work.
 97	  if (MOOD_PAUSES_ROAM.has(mood)) {
 98	    wake();
 99	    petRef?.clearRow();
100	    return false;
101	  }
102	
103	  const cfg = loadConfig();
104	  if (!cfg.enabled || cfg.mode === "stay") {
105	    handleStationary();
106	    return false;
107	  }
108	
109	  wake();
110	  const moved = await stepMode(cfg.mode);
111	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
112	    enterSleep();
113	  }
114	  return moved;
115	}
116	
117	/// Run one mode step and apply it. Returns true if the pet actually moved.
118	async function stepMode(mode: RoamMode): Promise<boolean> {
119	  const env = await fetchEnvironment(mode === "climb");
120	  if (!env) return false;
121	  const pos = await currentLogicalPos();
122	  if (!pos) return false;
123	
124	  const next = await runMode(mode, { env, pos, pet: petRef });
125	  const clamped = clampToBounds(next, env.workArea);
126	  if (Math.abs(clamped.x - pos.x) < 0.5 && Math.abs(clamped.y - pos.y) < 0.5) {
127	    return false;
128	  }
129	  lastMoveTs = Date.now();
130	  try { await setLogical(clamped); }
131	  catch (e) { void invoke("log_debug", { msg: `roam: setPosition error: ${e}` }).catch(() => {}); }
132	  return true;
133	}
134	
135	/// Pet is stationary (mode is stay or roaming disabled): maybe doze off.
136	function handleStationary(): void {
137	  if (mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
138	    enterSleep();
139	  } else {
140	    wake();
141	    petRef?.clearRow();
142	  }
143	}
